import{_ as t,o as l,c as e,a2 as i}from"./chunks/framework.CCCdsIgc.js";const g=JSON.parse('{"title":"团队","description":"","frontmatter":{},"headers":[],"relativePath":"guide/teams.md","filePath":"guide/teams.md"}'),r={name:"guide/teams.md"};function o(n,a,s,d,h,c){return l(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="团队" tabindex="-1">团队 <a class="header-anchor" href="#团队" aria-label="Permalink to &quot;团队&quot;">​</a></h1><p>团队是几位专家组成的小组，由主助手当<strong>队长</strong>：你说一件事，队长先列分工计划，你看过点「开始执行」，各位专家分头去做，做完交回队长，队长核对后给你一份汇总报告。</p><p>适合一个人一次做不完、又能拆开的事，比如「把这周交货延误的情况查清楚：MES 查工单、质检看不良、仓库看缺料，最后出一份报告」。一句话能问完的事，直接问专家或主助手更快。</p><p>团队模式要 IT 在安全中心打开才有，打开后侧栏出现「<strong>团队</strong>」。</p><h2 id="有哪些团队" tabindex="-1">有哪些团队 <a class="header-anchor" href="#有哪些团队" aria-label="Permalink to &quot;有哪些团队&quot;">​</a></h2><ul><li><strong>IT 下发的</strong>：IT 在后台建好，指定哪些部门能用；</li><li><strong>部门的</strong>：同部门同事建的，本部门的人都能看到、都能用；</li><li><strong>我自己的</strong>：只有你这台电脑能看到。电脑没登记部门时只能建个人团队。</li></ul><p>建团队的人和 IT 可以修改或解散；别人建的团队你可以「复制」一份改成自己的。</p><h2 id="建团队" tabindex="-1">建团队 <a class="header-anchor" href="#建团队" aria-label="Permalink to &quot;建团队&quot;">​</a></h2><ol><li>侧栏「团队」→「新建团队」；</li><li>起名字、写一句这个团队负责什么，选 2–8 位专家（IT 规定了上限的以后台为准），每位可以写一句分工说明；</li><li>可选：指定模型、关掉某几类工具（命令、写文件、浏览器、连接器、开发者工具）、设成只读；</li><li>选「部门共享」或「只有我」，保存。</li></ol><p>团队的设置只能让专家<strong>更收紧</strong>：关掉的工具专家用不了，设成只读后谁都不改东西；专家本来不能做的事，进了团队也不能做。</p><h2 id="交给团队一件事" tabindex="-1">交给团队一件事 <a class="header-anchor" href="#交给团队一件事" aria-label="Permalink to &quot;交给团队一件事&quot;">​</a></h2><ol><li>在团队卡片上点「<strong>开始任务</strong>」，输入要做的事；</li><li>队长先在输入框上方列出<strong>分工计划</strong>：每位专家做什么、做到什么程度算完成、要等谁的结果。你可以去掉某位专家、让队长改（写一句话），或取消。点「开始执行」之前什么都不会做；</li><li>开工前会问你一次这次团队可能用到的连接器查询，点「这次任务内都直接执行」后专家不再逐条问；命令、写文件、删除照旧到时候单独问；</li><li>右侧「<strong>团队</strong>」面板实时显示每位专家的状态（等待、进行中、重试、完成、失败），可以展开看每一步，也可以单独停掉某一位；「看板」里是专家们交出来的发现和文件，后面的专家能看到前面专家的结果；</li><li>全部做完后，队长核对各人的结果（标出达标、部分达标、缺信息、未完成，互相矛盾的地方会点出来），需要的话补派一轮（最多一轮、最多 3 位），最后给你汇总报告。</li></ol><p>查询类的专家可以同时开工，会改东西的专家一次只有一位在做，避免互相覆盖。</p><h2 id="安全和用量" tabindex="-1">安全和用量 <a class="header-anchor" href="#安全和用量" aria-label="Permalink to &quot;安全和用量&quot;">​</a></h2><ul><li>确认、拦截、审计和平时一样，删除、覆盖这类高危操作每次都问；</li><li>一次团队任务有用量上限（默认 100 万 token，IT 可调），超了会停下并告诉你；</li><li>每位专家的派遣都记在服务端，IT 能在后台看到。</li></ul>',15)])])}const u=t(r,[["render",o]]);export{g as __pageData,u as default};
